    web_search: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /**
                     * @description Two-letter language code (default `en`).
                     * @default null
                     */
                    lang?: string | null;
                    /** @description A short search query (it goes to the provider). */
                    query: string;
                    /**
                     * @description The subject as an article title (helps Wikipedia).
                     * @default null
                     */
                    topic?: string | null;
                };
            };
        };
        responses: {
            /** @description OK */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description The numbered passages, as the model gets them (empty: nothing found). */
                        context: string;
                        /**
                         * @description Pages this computer fetched itself.
                         * @default []
                         */
                        fetched: string[];
                        provider: components["schemas"]["Provider"];
                        query: string;
                        sources: components["schemas"]["Source"][];
                        /** Format: uint64 */
                        took_ms: number;
                    };
                };
            };
            /** @description Error */
            default: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
